#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
run_auto.sh 防护版 v2 部署包
============================
升级：A(cron多点) + B(单次内重试等待) + 防重复标记
用法: python3 deploy_run_auto_v2.py
"""
import base64, os
TARGET = "/root/bi_dashboard/v5scripts/run_auto.sh"
if os.path.exists(TARGET):
    import shutil
    shutil.copy(TARGET, TARGET + '.bak_v1')
    print(f'  已备份旧版 → {TARGET}.bak_v1')
BLOB = ""
with open(TARGET, 'wb') as f:
    f.write(base64.b64decode(BLOB))
os.chmod(TARGET, 0o755)
print(f'  已写入防护版 → {TARGET}')
print()
print('='*50)
print('✅ run_auto.sh 防护版 v2 部署完成')
print('   A+B+防重复标记，断网断电不怕')
print('='*50)
